package com.buildertoolbox.client.settings; import java.util.function.*; public class SettingBuilder<T,B extends SettingBuilder<T,B>> {protected String name="",description=""; protected T value; protected BooleanSupplier visible=()->true; protected Consumer<T> changed; protected double min=-Double.MAX_VALUE,max=Double.MAX_VALUE,sliderMin=0,sliderMax=10; protected boolean slider=true; @SuppressWarnings("unchecked") protected B self(){return (B)this;} public B name(String n){name=n;return self();} public B description(String d){description=d;return self();} public B defaultValue(T v){value=v;return self();} public B visible(BooleanSupplier v){visible=v;return self();} public B onChanged(Consumer<T> c){changed=c;return self();} public B min(double n){min=n;return self();} public B max(double n){max=n;return self();} public B range(double a,double b){min=a;max=b;return self();} public B sliderRange(double a,double b){sliderMin=a;sliderMax=b;return self();} public B sliderMax(double n){sliderMax=n;return self();} public B sliderMin(double n){sliderMin=n;return self();} public B noSlider(){slider=false;return self();} public Setting<T> build(){var setting=new Setting<>(name,description,value,visible,changed);setting.min=min;setting.max=max;setting.sliderMin=Math.max(min,sliderMin);setting.sliderMax=Math.min(max,sliderMax);setting.slider=slider;return setting;} }